    /**
     * Method to retrieve the Prediction via an PredictionPrimaryKey.
     * @param 	id Long
     * @return 	Prediction
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Prediction handle( FindPredictionQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getPredictionId() );
    }
    
    /**
     * Method to retrieve a collection of all Predictions
     *
     * @param	query	FindAllPredictionQuery 
     * @return 	List<Prediction> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Prediction> handle( FindAllPredictionQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindPrediction,
 * but only if the id matches
 *
 * @param		entity	Prediction
 */
	protected void emitFindPrediction( Prediction entity ) {
		LOGGER.info("handling emitFindPrediction" );
		
	    queryUpdateEmitter.emit(FindPredictionQuery.class,
	                            query -> query.getFilter().getPredictionId().equals(entity.getPredictionId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllPrediction
	 * 
	 * @param		entity	Prediction
	 */
	protected void emitFindAllPrediction( Prediction entity ) {
		LOGGER.info("handling emitFindAllPrediction" );
		
	    queryUpdateEmitter.emit(FindAllPredictionQuery.class,
	                            query -> true,
	                            entity);
	}

